  "cmp.sub": "ꯃꯈꯥꯗ ꯄꯤꯔꯤꯕ ꯇꯥꯛꯄꯁꯤꯡ ꯑꯁꯤ ꯃꯤꯅꯤꯁ꯭ꯠꯔꯤ ꯑꯣꯐ ꯍꯣꯝ ꯑꯦꯐꯥꯏꯔꯖꯒꯤ ꯁꯤꯇꯤꯖꯟ ꯃꯦꯅꯨꯑꯦꯜ ꯅꯠꯇ꯭ꯔꯒ ꯂꯣꯒꯤꯟ ꯄꯣꯔꯇꯦꯜꯗ ꯆꯥꯛꯂꯕ ꯆꯦꯛꯂꯤꯁ꯭ꯠ ꯂꯧꯈꯤꯕꯅꯤ, ꯑꯃꯁꯨꯡ ꯁꯣꯔꯁ ꯑꯗꯨ ꯃꯈꯥꯗ ꯂꯩ꯫ ꯑꯩꯈꯣꯏꯅ ꯍꯧꯖꯤꯛ ꯂꯩꯔꯤꯕ ꯑꯦꯛꯁꯄꯤꯔꯤꯑꯦꯟꯁ ꯑꯗꯨ ꯈꯟꯅꯔꯤꯗꯦ — ꯃꯁꯤ ꯂꯤꯔꯝꯃꯤ, ꯁꯥꯈꯤꯕ ꯃꯤꯑꯣꯏꯁꯤꯡꯅ꯫",
  "cmp.std.label": "ꯂꯩꯉꯥꯛꯀꯤ ꯃꯥꯏꯀꯩ ꯃꯇꯨꯡ ꯏꯟꯅ ꯊꯧꯔꯥꯡ ꯇꯧꯕ",
  "cmp.std.body": "ꯏꯟꯗꯤꯌꯥꯗ ꯃꯁꯤꯒꯤꯗꯃꯛ ꯗꯤꯖꯥꯏꯟ ꯁ꯭ꯇꯦꯟꯗꯔꯗ ꯂꯩꯗꯦ ꯍꯥꯏꯕ ꯅꯠꯇꯦ꯫ GIGW 3.0 ꯑꯁꯤ ꯁꯦꯟꯠꯔꯦꯜ ꯑꯃꯁꯨꯡ ꯁ꯭ꯇꯦꯠ ꯂꯩꯉꯥꯛꯀꯤ ꯋꯦꯕꯁꯥꯏꯠ ꯈꯨꯗꯤꯡꯃꯛꯇ ꯃꯊꯧ ꯇꯥꯏ: ꯆꯦꯛꯄꯣꯏꯟꯇ 88, WCAG 2.1 AA, ꯑꯃꯁꯨꯡ “enhancing user interface and user experience and the implementation of user-centric information architecture to ease the user journey.” MeitY ꯅ UX4G ꯐꯣꯡꯂꯤ, ꯃꯁꯤꯒꯤ ꯑꯣꯏꯕ ꯀꯝꯄꯣꯅꯦꯟꯇ ꯂꯥꯏꯕ꯭ꯔꯦꯔꯤ꯫ ꯔꯤꯗꯤꯖꯥꯏꯟ ꯑꯁꯤꯗ ꯑꯩꯈꯣꯏꯒꯤ ꯄꯥꯝꯕ ꯅꯠꯇꯦ꯫ ꯃꯁꯤ ꯂꯩꯉꯥꯛꯅ ꯃꯥꯅ ꯃꯥꯟꯅ ꯊꯝꯈꯤꯕ ꯕꯥꯔ ꯑꯗꯨꯅꯤ꯫",
  "cmp.stat.required": "ꯐꯣꯔꯝ ꯑꯗꯨ ꯊꯥꯗꯣꯛꯇꯕ ꯐꯤꯜꯗꯁꯤꯡ",
  "cmp.stat.relaxed": "ꯃꯈꯣꯏꯁꯤꯡꯗ ꯑꯩꯈꯣꯏꯅ ꯊꯤꯡꯗꯕꯁꯤꯡ",
