  "cmp.stat.lost": "ꯅꯍꯥꯛꯅ ꯑꯥꯏꯗꯦꯟꯇꯤꯐꯥꯏ ꯇꯧꯕ ꯌꯥꯕ ꯀꯤꯁ꯭ꯠꯔꯣꯛ",
  "cmp.h2": "ꯍꯧꯖꯤꯛ ꯐꯣꯔꯝ ꯑꯁꯤꯅ ꯃꯤꯁꯤꯡꯒꯤ ꯀꯝꯄ꯭ꯂꯦꯟꯇ ꯃꯥꯡꯍꯟꯂꯤꯕ ꯃꯐꯝ ꯇꯔꯥ",
