  "cmp.shotsSub": "cybercrime.gov.in ꯑꯃꯁꯨꯡ ꯃꯅꯤ ꯔꯦꯁ꯭ꯇꯣꯔꯦꯁꯟ ꯄꯣꯔꯇꯦꯜꯒꯤ ꯄꯕ꯭ꯂꯤꯛ ꯁ꯭ꯀ꯭ꯔꯤꯟꯁꯤꯡ, ꯇꯥꯛꯂꯤꯕ ꯆꯩꯀꯤ ꯃꯇꯝꯗ ꯂꯧꯈꯤꯕ꯫ ꯀꯝꯄ꯭ꯂꯦꯟꯇ ꯑꯃꯅ ꯍꯧꯖꯤꯛ ꯐꯥꯏꯜ ꯇꯧꯔꯤꯕ ꯑꯗꯨ ꯇꯥꯛꯅꯕ ꯍꯥꯏꯖꯤꯜꯂꯤ꯫ ꯀꯥꯚꯆ ꯑꯁꯤ ꯂꯩꯉꯥꯛꯀꯤ ꯁꯔꯚꯤꯁ ꯅꯠꯇꯦ, ꯃꯁꯤꯒꯤ ꯃꯥꯔꯛ ꯀꯅꯥꯠꯇ ꯂꯩꯗꯦ, ꯑꯃꯁꯨꯡ ꯀꯅꯥꯒꯤꯇ ꯄꯥꯜꯂꯝꯗꯦ ꯅꯠꯇ꯭ꯔꯒ ꯁꯥꯄꯣꯔ꯭ꯠ ꯇꯧꯗꯦ꯫",
  "cmp.captured": "ꯂꯧꯈꯤ",
  "cmp.shot.login": "ꯀ꯭ꯔꯥꯏꯝ ꯑꯗꯨꯒꯤ ꯃꯔꯝꯗ ꯏꯕꯒꯤ ꯃꯃꯥꯡꯗ, ꯄꯣꯔꯇꯦꯜ ꯑꯗꯨꯅ ꯃꯤꯡ ꯑꯃ, ꯃꯣꯕꯥꯏꯜ ꯅꯝꯕꯔ ꯑꯃ ꯑꯃꯁꯨꯡ OTP ꯑꯃ ꯍꯪꯏ — ꯑꯃꯁꯨꯡ ꯂꯩꯀꯥꯏ ꯂꯩꯉꯥꯛꯀꯤ ꯏꯗꯦꯟꯇꯤꯇꯤ ꯗꯣꯀꯨꯃꯦꯟꯇ 5 MB ꯃꯈꯥꯗ ꯑꯃꯁꯨꯡ ꯀꯔꯝꯅ ꯏꯁꯤꯡ ꯇꯥꯛꯄ ꯀꯥꯏꯗꯕ # $ @ ^ * ~ | ! ꯂꯩꯗꯕ ꯆꯥꯔꯦꯛꯇꯔ 200 ꯀꯥꯏꯗꯕ ꯇꯥꯛꯄ ꯆꯦꯛꯂꯤꯁ꯭ꯠ ꯑꯃ ꯄꯤꯔꯤ꯫",
  "cmp.shot.accept": "ꯀꯝꯄ꯭ꯂꯦꯟꯇ ꯖꯔꯅꯤ ꯑꯁꯤ ꯄ꯭ꯔꯣꯖꯤꯡꯒꯤ ꯊꯣꯡꯅꯥꯎ ꯑꯃꯗ ꯍꯧꯏ, ꯃꯁꯤ ꯀꯔꯤꯒꯤ ꯃꯃꯥꯡꯗ ꯑꯦꯛꯁꯦꯞꯠ ꯇꯧꯒꯗꯕꯅꯤ꯫",
  "cmp.shot.home": "ꯃꯤꯑꯣꯏ ꯑꯃꯅ ꯇꯣꯏꯅ ꯈꯟꯒꯗꯕ ꯂꯝꯕꯤ ꯑꯍꯨꯝ ꯀꯥꯡꯂꯥꯏ — ꯑꯃꯁꯨꯡ ꯃꯈꯣꯏꯒꯤ ꯃꯔꯝ ꯇꯥꯛꯄ ꯀꯅꯥꯇ ꯂꯩꯗꯦ꯫ ꯃꯈꯥꯗ, ꯂꯥꯏꯅꯔꯅꯤꯡ ꯀꯣꯔꯅꯔ ꯗꯣꯀꯨꯃꯦꯟꯇ ꯃꯔꯤ ꯄꯥꯏꯔꯤ꯫",
  "cmp.shot.suspect": "ꯁꯁ꯭ꯄꯦꯛꯇ ꯔꯦꯄꯣꯖꯤꯇꯔꯤ, ꯃꯁꯤꯅ ꯀꯅꯥꯒꯤꯇ ꯅꯝꯕꯔ ꯅꯠꯇ꯭ꯔꯒ UPI ꯑꯥꯏ.ꯗꯤ. ꯑꯃ ꯑꯇꯩ ꯃꯤꯁꯤꯡꯅ ꯔꯦꯄꯣꯔꯠ ꯇꯧꯔꯕ ꯑꯦꯗꯦꯟꯇꯤꯐꯥꯏꯌꯔꯁꯤꯡꯒ ꯆꯥꯡꯗꯝꯅꯕ ꯌꯥꯍꯜꯂꯤ꯫ ꯃꯁꯤ ꯌꯥꯝꯅ ꯀꯨꯏꯔꯤ ꯑꯃꯁꯨꯡ ꯀꯅꯥꯇ ꯈꯪꯗꯦ ꯃꯁꯤ ꯃꯐꯝ ꯑꯗꯨꯗ ꯂꯩꯈꯤꯗꯦ꯫",
  "cmp.shot.mrm": "ꯈꯨꯗꯣꯜ ꯑꯃꯨꯛ ꯍꯟꯅꯥ ꯐꯪꯅꯕꯥ ꯄꯣꯔꯇꯦꯜ ꯑꯁꯤꯅꯥ ꯁ꯭ꯇꯥꯏ ꯇꯧꯔꯕꯥ ꯁꯦꯟꯖꯨꯝ ꯊꯝꯂꯦ ꯍꯥꯏꯅꯥ ꯆꯦꯛ ꯇꯧꯔꯕꯥ ꯃꯇꯨꯡꯗꯥ ꯆꯠꯅꯕꯥ ꯌꯥꯕꯥ ꯂꯝꯖꯦꯜ ꯑꯃꯥ ꯄꯤꯏ꯫ ꯊꯝꯕꯥ ꯑꯁꯤ ꯑꯃꯨꯛ ꯍꯟꯅꯥ ꯄꯤꯕꯥ ꯅꯠꯇꯦ, ꯑꯃꯁꯨꯡ ꯊꯥꯗꯣꯀꯄꯥ ꯑꯁꯤ ꯆꯠꯅꯕꯥ ꯃꯇꯝ ꯊꯧꯔꯥꯡꯒꯤ ꯃꯇꯨꯡ ꯏꯟꯅꯥ ꯆꯠꯂꯤ꯫",
  "cmp.honest.label": "ꯃꯁꯤꯒꯤ ꯆꯥꯡꯗꯝꯅꯕ ꯑꯁꯤ ꯀꯔꯤ ꯅꯠꯇꯦ",
  "cmp.honest.body": "ꯄꯣꯔꯇꯦꯜ ꯑꯁꯤꯅꯥ ꯑꯩꯈꯣꯌꯅꯥ ꯇꯧꯗꯕꯥ ꯊꯕꯛ ꯈꯔꯥ ꯇꯧꯏ꯫ ꯃꯁꯤꯅꯥ ꯀꯣꯝꯞꯂꯦꯟꯇꯁꯤꯡ ꯑꯗꯨ ꯃꯔꯤ ꯂꯩꯅꯕꯥ ꯁ꯭ꯇꯦꯠ ꯅꯠꯇ꯭ꯔꯒꯥ ꯌꯨ.ꯇꯤ. ꯂꯥꯏꯅꯀꯤ ꯊꯕꯛ ꯄꯥꯏꯅꯕꯥ ꯑꯦꯖꯦꯟꯁꯤꯗꯥ ꯔꯧꯠ ꯇꯧꯏ, ꯑꯦꯀꯅꯣꯂꯦꯖꯃꯦꯟꯇ ꯑꯃꯥ ꯊꯣꯀꯍꯜꯂꯤ, ꯑꯃꯁꯨꯡ ꯁꯦꯟꯒꯤ ꯑꯣꯏꯕꯥ ꯂꯥꯏꯅꯀꯤ ꯊꯕꯛ ꯇꯧꯕꯁꯤꯡ ꯑꯗꯨ CFCFRMS ꯀꯥꯡꯂꯥꯏꯗ ꯁꯔꯨꯛ ꯌꯥꯔꯤꯕꯥ ꯏꯟꯁ꯭ꯇꯤꯇ꯭ꯌꯨꯁ꯭ꯅꯁꯤꯡꯒꯥ ꯅꯀꯛꯅꯥ ꯊꯝꯂꯤ ꯃꯗꯨꯅꯥ ꯃꯈꯣꯌꯅꯥ ꯁꯦꯟꯒꯤ ꯂꯝꯖꯦꯜ ꯑꯗꯨꯗꯥ ꯊꯕꯛ ꯇꯧꯅꯕꯥ ꯍꯣꯠꯅꯕꯥ ꯌꯥꯏ꯫ ꯑꯦꯀꯅꯣꯂꯦꯖꯃꯦꯟꯇ ꯑꯃꯥ ꯑꯁꯤ FIR ꯑꯃꯥ ꯅꯠꯇꯦ, ꯊꯝꯕꯥ ꯑꯁꯤ ꯑꯃꯨꯛ ꯍꯟꯅꯥ ꯄꯤꯕꯥ ꯅꯠꯇꯦ, ꯑꯃꯁꯨꯡ ꯀꯔꯤꯒꯨꯝꯕꯥ ꯑꯃꯠꯇꯥ ꯂꯥꯀꯈꯤꯗ꯭ꯔꯦ꯫ ꯃꯐꯝ ꯑꯁꯤꯗꯥ ꯀꯔꯤꯒꯨꯝꯕꯥ ꯑꯃꯠꯇꯥ ꯂꯥꯏꯅꯀꯤ ꯁꯤꯁ꯭ꯇꯦꯝ ꯑꯃꯗꯥ ꯊꯥꯗꯦ꯫ ꯃꯁꯤ ꯍꯥꯏꯖꯤꯟꯅꯕꯥ ꯁꯦꯃꯈꯤꯕꯥ ꯈ꯭ꯋꯥꯏꯗꯒꯤ ꯉꯥꯛꯇꯨꯅꯥ ꯊꯝꯕꯥ ꯐꯤꯜ ꯑꯃꯥ ꯎꯠꯄꯅꯤ—ꯄꯣꯔꯇꯦꯜ ꯆꯂꯥꯏꯔꯤꯕꯥ ꯃꯤꯑꯣꯏꯁꯤꯡꯒꯤ ꯃꯥꯌꯣꯛꯇꯥ ꯑꯥꯏꯅꯥ ꯅꯠꯇꯦ꯫",
