  "esc.sub": "ꯑꯣꯐꯤꯁꯤꯑꯦꯜ ꯑꯣꯏꯕ ꯀꯝꯞꯂꯦꯟꯠ ꯑꯃꯥ ꯊꯕꯛ ꯂꯩꯇ꯭ꯔꯕꯗꯥ, ꯍꯧꯖꯤꯛ ꯎꯕ ꯐꯪꯗꯕ ꯊꯧꯔꯥꯡ ꯑꯃꯥ ꯂꯩꯔꯒꯗꯥ, ꯍꯧꯖꯤꯛ ꯂꯩꯔꯤꯕ ꯊꯥꯛ ꯑꯃꯗꯤ ꯂꯧꯁꯤꯟꯕ ꯑꯣꯐꯤꯁ ꯑꯗꯨ ꯈꯪꯗꯣꯛꯎ꯫ ꯊꯣꯛꯈꯤꯕ ꯁ꯭ꯇꯦꯠ/UT Nodal ꯑꯃꯗꯤ ꯒ꯭ꯔꯤꯚꯦꯟꯁ ꯀꯣꯟꯇꯦꯛꯁꯤꯡꯅ ꯂꯝꯕꯤ ꯑꯃꯥ ꯄꯤꯕ ꯌꯥꯏ; ꯃꯈꯣꯏꯒꯤ ꯊꯧꯗꯥꯡꯅ ꯊꯤꯖꯤꯟꯕ ꯅꯠꯇꯥꯛꯅ ꯊꯣꯛꯈꯤꯕ ꯊꯧꯔꯥꯡ ꯑꯃꯥ ꯀꯥꯟꯅꯗ ꯂꯩꯍꯟꯗꯦ꯫",
