  "esc.io.b": "NCRP ꯀꯅꯐꯔꯃꯦꯁꯟ ꯑꯃꯅ ꯐꯤꯔ ꯔꯦꯖꯤꯁꯇꯔ ꯇꯧꯈ꯭ꯔꯦ ꯅꯠꯇꯥꯛꯅ ꯊꯤꯖꯤꯟꯕ ꯑꯣꯐꯤꯁꯔ ꯑꯃꯥ ꯈꯅꯈ꯭ꯔꯦ ꯍꯥꯏꯕ ꯑꯗꯨ ꯎꯠꯇꯦ꯫ ꯂꯧꯔꯤꯕ ꯄꯣꯂꯤꯁ ꯌꯨꯅꯤꯠ ꯑꯗꯨꯗ ꯍꯧꯖꯤꯛ ꯂꯩꯔꯤꯕ ꯊꯥꯛ ꯑꯗꯨ ꯍꯪꯎ ꯑꯃꯗꯤ ꯈꯅꯈ꯭ꯔꯕꯗꯥ, ꯑꯣꯐꯤꯁꯔꯒꯤ ꯑꯣꯐꯤꯁꯤꯑꯦꯜ ꯀꯣꯟꯇꯦꯛ ꯅꯠꯇꯥꯛꯅ ꯊꯥꯛ ꯑꯗꯨ ꯍꯪꯎ꯫ ꯃꯈꯣꯏꯅ ꯁꯛꯇꯤ ꯄꯤꯔꯤꯕ ꯑꯗꯨ ꯔꯦꯀꯣꯔꯗ ꯇꯧꯎ꯫",
