  "esc.nodal.b": "ꯍꯧꯖꯤꯛ ꯂꯩꯔꯤꯕ ꯁ꯭ꯇꯦꯠ/UT ꯁꯥꯏꯛꯕꯔ Nodal ꯑꯣꯐꯤꯁꯔꯒꯤ ꯀꯣꯟꯇꯦꯛ ꯑꯗꯨ ꯁꯤꯖꯤꯟꯅꯗꯨꯅ ꯀꯝꯞꯂꯦꯟꯠ ꯑꯗꯨ ꯀꯔꯤꯗ ꯊꯥꯈꯤ ꯑꯃꯗꯤ ꯀꯔꯤ ꯊꯕꯛ ꯂꯧꯈꯠꯈꯤ, ꯀꯔꯤꯝꯕ ꯑꯃꯥ ꯔꯦꯀꯣꯔꯗ ꯇꯧꯔꯕꯗꯤ ꯍꯪꯎ꯫ ꯊꯧꯔꯥꯡ ꯇꯧꯔꯕ ꯏꯃꯦꯜ ꯑꯗꯨ ꯅꯍꯥꯛꯅ ꯌꯦꯡꯅꯕ ꯑꯃꯗꯤ ꯊꯥꯅꯕ ꯗ꯭ꯔꯥꯐꯠ ꯑꯃꯅꯤ; Kavach ꯅ ꯊꯥꯗꯦ꯫",
  "esc.griev.t": "ꯑꯗꯨꯒ ꯒ꯭ꯔꯤꯚꯦꯟꯁ ꯑꯣꯐꯤꯁꯔ",
