  "esc.court.b": "ꯀꯅꯐꯔꯝ ꯇꯧꯔꯕ ꯂꯨꯞꯇ ꯂꯩꯔꯤꯕ ꯄꯥꯏꯁꯥ ꯊꯥꯗꯣꯛꯄꯅ ꯀꯦꯁ ꯑꯗꯨꯒꯤ ꯃꯇꯨꯡ ꯏꯟꯅ ꯀꯣꯔꯠ, ꯄꯣꯂꯤꯁ ꯑꯃꯗꯤ ꯕꯦꯉ꯭ꯛꯀꯤ ꯊꯧꯔꯥꯡ ꯑꯃꯥ ꯈꯥꯏꯗꯣꯛꯄ ꯌꯥꯏ; ꯈꯅꯈꯤꯕ ꯁꯦꯛꯁꯟ ꯑꯃꯗ ꯊꯥꯅ ꯊꯥꯗꯣꯛꯄ ꯌꯥꯏ ꯍꯥꯏꯅ ꯊꯥꯅꯗ ꯊꯝꯀꯅꯨ꯫ ꯊꯤꯖꯤꯟꯕ ꯌꯥꯕ ꯔꯦꯒ꯭ꯌꯨꯂꯦꯇꯦꯗ ꯏꯟꯇꯤꯇꯤ ꯑꯃꯒꯤ ꯃꯥꯟꯅꯗ ꯀꯝꯞꯂꯦꯟꯠ ꯑꯃꯒꯤꯗꯃꯛ, 2026 RBI ꯑꯣꯝꯕꯨꯗ꯭ꯁꯃꯦꯟ ꯂꯝꯕꯤ ꯑꯗꯨ ꯆꯠꯅꯕ ꯌꯥꯕ ꯕꯦꯉ꯭ꯛꯅ ꯍꯧꯅ ꯄꯤꯕ ꯏꯊꯧ ꯃꯇꯝ ꯑꯗꯨꯒꯤ ꯃꯇꯨꯡꯗ ꯍꯥꯡꯗꯣꯛꯄ ꯌꯥꯏ꯫ NALSA ꯒꯤ 15100 ꯍꯦꯜꯞꯂꯥꯏꯟ ꯅ ꯂꯦꯒꯦꯜ ꯁꯔꯚꯤꯁ ꯐꯪꯕ ꯌꯥꯕ ꯊꯥꯛ ꯑꯗꯨ ꯈꯪꯍꯟꯕ ꯌꯥꯏ꯫",
