  "intake.childBody": "ꯑꯉꯥꯡ ꯑꯃ ꯑꯥꯏꯕꯥ ꯂꯩꯔꯛꯂꯕꯗꯤ 112 ꯈꯥꯡꯗꯨꯅ ꯈꯟꯐꯝꯕꯤꯗꯨꯅ ꯈꯟꯗ꯭ꯔꯤꯅ ꯀꯧꯕꯤꯜꯂꯨ. ꯑꯉꯥꯡ ꯉꯥꯛꯊꯣꯛꯅꯕ 1098 ꯀꯧꯕꯤꯜꯂꯨ. ꯂꯥꯏꯛꯂꯤꯛ ꯑꯣꯏꯕ ꯁꯛꯇꯝꯁꯤꯡ ꯅꯠꯇ꯭ꯔꯒ ꯚꯤꯗꯤꯑꯣꯁꯤꯡ ꯑꯁꯤ ꯃꯐꯝ ꯑꯁꯤꯗ ꯊꯥꯗꯣꯛꯄ, ꯑꯅꯧꯕ ꯀꯣꯄꯤꯁꯤꯡ ꯊꯤꯟꯕ ꯅꯠꯇ꯭ꯔꯒ ꯊꯥꯗꯣꯛꯄ ꯇꯧꯒꯅꯨ. ꯃꯁꯤꯒꯤ ꯄ꯭ꯔꯣꯇꯣꯇꯥꯏꯞ ꯑꯁꯤꯗ ꯃꯊꯧ ꯇꯥꯕ ꯂꯥꯏꯅ-ꯊꯝꯕ ꯂꯥꯟꯊꯣꯛ-ꯂꯥꯟꯅ ꯄꯥꯎꯗꯣꯛꯅꯕ ꯀꯥꯡꯂꯨꯞ ꯑꯃꯠꯇ ꯂꯩꯇꯦ; ꯊꯥꯖꯕ ꯌꯥꯕ ꯑꯆꯧꯕ ꯃꯤꯑꯣꯏ ꯑꯃꯅ ꯅꯠꯇ꯭ꯔꯒ ꯇꯝꯈ꯭ꯔꯕ ꯃꯤꯑꯣꯏ ꯑꯃꯅ ꯂꯧꯊꯣꯛꯀꯗꯕꯅꯤ.",
