  "intake.rbiReportNo": "ঐꯅꯥ ꯕꯦꯅꯛꯇꯥ ꯈꯪꯍꯟꯈꯤꯗꯦ",
  "intake.rbiReviewQ": "ꯃꯁꯤꯅꯥ ꯄꯥꯎꯈꯨꯝꯁꯤꯡ ꯑꯁꯤꯅꯥ RBI ꯉꯥꯛꯊꯣꯛ-ꯁꯦꯜꯂꯤꯕꯥ ꯂꯝꯕꯤ ꯀꯔꯤ ꯁꯤꯖꯤꯟꯅꯒꯅꯤ ꯍꯥꯏꯕꯗꯥ ꯍꯣꯡꯗꯣꯛꯂꯤ. ꯃꯁꯤꯗꯥ ꯊꯥꯖꯅꯤꯡꯉꯥꯏ ꯑꯣꯏꯕꯥ ꯑꯃꯁꯨꯡ ꯂꯝꯕꯤ ꯈꯪꯅꯕꯥ ꯊꯤꯖꯤꯟꯕꯥ ꯑꯃꯥ ꯌꯥꯎꯔꯤ, ꯂꯨꯄꯥ ꯍꯜꯂꯛꯀꯅꯤ ꯍꯥꯏꯕꯥ ꯀꯥꯛꯊꯠꯂꯗꯦ.",
