  "intake.waPrivateBody": "ꯋꯥꯠꯁꯑꯥꯞ ꯄ꯭ꯔꯤꯚꯤꯌꯨ ꯑꯁꯤ ꯅꯍꯥꯛꯀꯤ ꯋꯥꯍꯧꯊꯣꯛ, ꯈꯪꯗꯣꯛꯅꯕꯥ ꯈꯨꯗꯝꯁꯤꯡ, ꯕꯦꯉ꯭ꯀꯀꯤ ꯋꯥꯐꯝꯁꯤꯡ ꯅꯠꯇ꯭ꯔꯒ ꯁꯛꯇꯤ ꯄꯤꯕꯥ ꯈꯨꯗꯝꯁꯤꯡꯒꯤ ꯃꯃꯥꯡꯗꯥ ꯂꯦꯞꯂꯦ꯫ ꯅꯍꯥꯛꯅꯥ ꯍꯥꯟꯅꯥ ꯄꯤꯔꯕꯥ ꯏꯀꯥꯏꯈꯨꯗꯨꯅꯥ ꯂꯩꯕꯥ ꯀꯥꯚꯆ ꯋꯦꯕ ꯈꯟꯅ-ꯅꯩꯅꯕꯥ ꯑꯗꯨꯗꯥ ꯃꯊꯪ ꯆꯠꯊꯈꯤꯂꯨ꯫",
