  "intake.vaaniTitle": "ꯕꯥꯅꯤ ꯋꯥꯍꯩ ꯈꯟꯅ-ꯅꯩꯅꯕꯥ",
  "intake.vaaniBody": "ꯕꯥꯅꯤ ꯍꯥꯌꯕꯁꯤꯁꯤ ꯈꯅꯅꯥ ꯂꯧꯕꯥ ꯑꯥꯏ.ꯑꯥꯏ. (AI) ꯋꯥꯍꯩ ꯄꯨꯊꯣꯛꯄꯥ ꯑꯃꯅꯤ, ꯄꯣꯂꯤꯁ ꯅꯠꯇꯦ, ꯂꯩꯀꯥꯏ ꯂꯩꯉꯥꯛ ꯅꯠꯇꯦ, ꯈꯨꯗꯀꯤ ꯊꯕꯛ ꯇꯧꯕꯥ ꯈꯨꯠꯂꯥꯏ ꯅꯠꯇꯦ ꯑꯃꯁꯨꯡ ꯃꯤꯑꯣꯢ ꯀꯅꯥꯒꯨꯝꯕꯥ ꯑꯃꯁꯨ ꯅꯠꯇꯦ꯫ ꯉꯥꯛꯁꯦꯜ ꯑꯃꯁꯨꯡ ꯆꯍꯤꯒꯤ ꯆꯦꯛꯁꯤꯟꯅꯥ ꯌꯦꯡꯕꯥ ꯑꯗꯨ ꯂꯣꯏꯗ꯭ꯔꯤꯉꯩꯗꯥ ꯋꯥꯍꯩ ꯍꯥꯏꯕꯁꯤ ꯊꯤꯟꯗꯨꯅꯥ ꯊꯝꯃꯤ, ꯑꯃꯁꯨꯡ ꯅꯍꯥꯛꯅꯥ ꯊꯤꯟꯗꯨꯅꯥ ꯌꯦꯡꯗ꯭ꯔꯤꯉꯩꯗꯥ ꯀꯅꯥꯒꯨꯝꯕꯥ ꯇ꯭ꯔꯥꯟꯁꯀ꯭ꯔꯤꯞ ꯈꯨꯗꯛꯇꯥ ꯅꯍꯥꯛꯀꯤ ꯑꯦꯀꯥꯎꯟꯇꯇꯥ ꯆꯪꯗꯦ꯫",
  "intake.vaaniLocked": "ꯃꯈꯥꯗꯥ ꯄꯤꯔꯤꯕꯥ ꯈꯨꯗꯝ ꯑꯍꯨꯝꯅꯥ ꯍꯪꯕꯥ ꯋꯥꯍꯪꯁꯤꯡꯒꯤ ꯃꯇꯨꯡꯗꯥ ꯋꯥꯍꯩ ꯍꯥꯏꯕꯁꯤ ꯍꯥꯡꯗꯣꯛꯏ: ꯈꯨꯗꯝ ꯂꯥꯛꯀꯅꯥ ꯍꯥꯏꯕꯥ ꯋꯥꯍꯩ, ꯅꯍꯥꯛ ꯍꯧꯖꯤꯛ ꯍꯥꯟꯅꯥ ꯉꯥꯛꯁꯦꯜ ꯂꯩꯕꯥ ꯅꯠꯇ꯭ꯔꯒ ꯅꯠꯇꯦ ꯑꯃꯁꯨꯡ ꯑꯉꯥꯡ ꯑꯃꯥ ꯌꯥꯎꯕꯥ ꯑꯃꯥ ꯌꯥꯎꯗꯦ꯫ ꯅꯍꯥꯛꯅꯥ ꯃꯈꯥ ꯇꯥꯅꯥ ꯏꯕꯥ ꯑꯗꯨ ꯃꯈꯥ ꯇꯥꯅꯥ ꯆꯠꯊꯕꯥ ꯌꯥꯏ꯫",
  "intake.vaaniDemo": "ꯕꯥꯅꯤ ꯑꯁꯤ ꯃꯐꯝ ꯑꯁꯤꯗꯥ ꯁꯦꯃꯗꯣꯛꯈꯤꯗꯦ꯫ ꯈꯟꯅ-ꯅꯩꯅꯕꯥ ꯑꯗꯥꯨꯗꯥ ꯃꯛꯔꯣꯐꯣꯟ ꯁꯤꯖꯤꯟꯅꯥꯏ, ꯅꯠꯇ꯭ꯔꯒ ꯆꯦꯛꯁꯤꯟꯅꯥ ꯈꯪꯗꯣꯛꯅꯕꯥ ꯁꯝꯄꯜ ꯀꯣꯜ ꯑꯃꯥ ꯂꯣꯗ ꯇꯧꯅꯥꯏ꯫",
  "intake.vaaniLive": "ꯀꯟꯠꯔꯣꯜ ꯇꯧꯔꯕꯥ ꯕꯥꯅꯤ ꯇꯦꯁ꯭ꯠ ꯀꯣꯜꯕꯦꯛ ꯑꯁꯤ ꯑꯦꯂꯣꯂꯤꯁ꯭ꯠ ꯇꯧꯔꯕꯥ ꯈꯨꯗꯝꯁꯤꯡꯒꯤꯗꯃꯛ ꯐꯪꯏ",
