  "intake.vaaniPhone": "ꯀꯣꯜ ꯇꯧꯅꯕꯥ ꯈꯨꯗꯝ, ꯂꯩꯄꯥꯛꯀꯤ ꯈꯨꯗꯝꯁꯤꯡꯒꯥ ꯂꯣꯌꯅꯅꯥ",
  "intake.vaaniSafe": "ꯍꯧꯖꯤꯛ ꯀꯣꯜ ꯑꯁꯤꯗꯥ ꯂꯧꯕꯥ ꯑꯃꯁꯨꯡ ꯋꯥꯍꯩ ꯍꯥꯏꯕꯥ ꯑꯁꯤ ꯅꯍꯥꯛꯀꯤꯗꯃꯛ ꯉꯥꯛꯁꯦꯜ ꯂꯩ꯫",
  "intake.vaaniConsent": "ꯑꯩꯈꯣꯢꯅꯥ ꯄꯤꯔꯤꯕꯥ ꯀꯣꯜ ꯐꯪꯒꯤ ꯑꯃꯁꯨꯡ ꯀꯥꯚꯆꯅꯥ ꯕꯥꯅꯤ ꯑꯥꯏ.ꯑꯥꯏ. (AI) ꯗꯥ ꯍꯧꯖꯤꯛ ꯑꯦꯂꯣꯂꯤꯁ꯭ꯠ ꯇꯧꯔꯕꯥ ꯈꯨꯗꯝ ꯑꯁꯤꯗꯥ ꯀꯣꯜ ꯇꯧꯅꯕꯥ ꯍꯥꯏꯖꯤꯅꯂꯦ꯫ ꯀꯦꯔꯤꯌꯔ ꯆꯥꯔꯖꯁꯤꯡ ꯂꯧꯕꯥ ꯌꯥꯏ꯫",
  "intake.vaaniDataConsent": "ꯑꯩꯅꯥ ꯀꯦꯁ ꯗ꯭ꯔꯥꯐ꯭ꯠ ꯑꯃꯥ ꯃꯐꯝ ꯑꯁꯤꯗꯥ ꯌꯦꯡꯁꯤꯟꯅꯕꯥ ꯈꯛꯇꯥ ꯑꯩꯅꯥ ꯍꯥꯏꯔꯤꯕꯁꯤꯡ ꯕꯥꯅꯤꯅꯥ ꯁꯦꯃꯖꯤꯟ ꯁꯥꯖꯤꯟ ꯇꯧꯕꯥ ꯑꯃꯁꯨꯡ ꯇ꯭ꯔꯥꯟꯁꯀ꯭ꯔꯤꯞ ꯇꯧꯕꯥ ꯑꯗꯨꯗꯥ ꯂꯥꯏ ꯌꯥꯅꯔꯦ꯫",
  "intake.vaaniRecordingConsent": "ꯕꯥꯅꯤ ꯁꯦꯃꯖꯤꯟ ꯁꯥꯖꯤꯟ ꯑꯁꯤꯅꯥ ꯀꯣꯜ ꯑꯃꯁꯨꯡ ꯇ꯭ꯔꯥꯟꯁꯀ꯭ꯔꯤꯞ ꯑꯗꯨ ꯊꯝꯕꯥ ꯑꯃꯁꯨꯡ ꯊꯤꯟꯗꯨꯅꯥ ꯊꯝꯕꯥ ꯌꯥꯏ ꯍꯥꯌꯕꯥ ꯑꯗꯨ ꯑꯩꯅꯥ ꯈꯪꯉꯤ, ꯑꯃꯁꯨꯡ ꯑꯩꯅꯥ ꯊꯤꯟꯗꯨꯅꯥ ꯊꯝꯕꯥ ꯑꯗꯨ ꯈꯥꯏꯗꯣꯛꯅꯥ ꯂꯥꯏ ꯌꯥꯅꯔꯦ꯫",
  "intake.vaaniPrivacy": "ꯕꯥꯅꯤꯒꯤ ꯐꯣꯡꯗꯣꯛꯂꯕꯥ ꯉꯥꯛꯁꯦꯜ ꯈꯪꯗꯣꯛꯅꯕꯥ ꯆꯦꯛꯁꯤꯟꯅꯥ ꯌꯦꯡꯕꯥ ꯑꯗꯨꯅꯥ ꯍꯥꯌꯔꯤ ꯀꯣꯜ ꯔꯦꯀꯣꯔꯗ ꯑꯃꯁꯨꯡ ꯇ꯭ꯔꯥꯟꯁꯀ꯭ꯔꯤꯞꯁꯤꯡ ꯑꯗꯨ ꯊꯥ ꯲꯴ ꯐꯥꯑꯣꯕꯥ ꯊꯤꯟꯗꯨꯅꯥ ꯊꯝꯕꯥ ꯌꯥꯏ ꯑꯃꯁꯨꯡ ꯈꯪꯅꯕꯥ ꯄꯣꯠꯂꯝꯁꯤꯡ ꯑꯗꯨ ꯏꯟꯗꯤꯌꯥꯒꯤ ꯃꯊꯛꯇꯥ ꯊꯕꯛ ꯇꯧꯕꯥ ꯌꯥꯏ꯫ ꯃꯗꯨ ꯌꯥꯅꯤꯡꯗꯦ ꯍꯥꯌꯅꯥ ꯂꯥꯛꯂⴰꯗꯥ ꯍꯧꯗꯣꯀꯀꯅꯥ; ꯃꯗꯨꯒꯤ ꯃꯍꯨꯠꯇꯥ ꯑꯂꯤꯅꯕꯥ ꯊꯝꯃꯨ꯫ ꯄꯨꯊꯣꯛꯄꯥ ꯁꯤꯖꯤꯟꯅꯕꯥ ꯑꯁꯤꯗꯥ ꯀꯟꯠꯔꯦꯛꯇ ꯇꯧꯔꯕꯥ ꯆꯦꯛꯁꯤꯟꯅꯥ ꯌꯦꯡꯕꯥ, ꯊꯤꯗꯣꯛꯄꯥ ꯑꯃꯁꯨꯡ ꯍꯥꯏꯊꯍꯟꯅꯕꯥ ꯈꯨꯠꯂꯥꯏꯁꯤꯡ ꯃꯊꯧ ꯇꯥꯏ꯫",
  "intake.vaaniStorageRequired": "ꯂꯥꯏꯚ ꯀꯣꯜꯕꯦꯛ ꯑꯁꯤ ꯊꯤꯟꯈ꯭ꯔꯦ ꯃꯔꯝꯗꯤ ꯇꯦꯕ ꯑꯁꯤꯅꯥ ꯏꯗꯦꯝꯄꯣꯇꯦꯟꯁꯤ ꯔꯦꯁꯤꯠ ꯑꯃꯥ ꯊꯤꯟꯗꯨꯅꯥ ꯊꯝꯕꯥ ꯉꯝꯗꯦ꯫ ꯔꯦꯁꯤꯠ ꯑꯗꯨ ꯌꯥꯎꯗꯅꯥ, ꯆꯦꯅꯦꯜ ꯍꯣꯡꯗꯣꯛꯄꯥ ꯅꯠꯇ꯭ꯔꯒ ꯑꯃꯨꯛ ꯂꯣꯗ ꯇꯧꯕꯥ ꯑꯁꯤꯅꯥ ꯑꯅꯤꯔꯨꯛ ꯀꯣꯜ ꯑꯃꯥ ꯊꯝꯕꯥ ꯌꯥꯏ꯫ ꯑꯂꯤꯅꯕꯥ ꯊꯝꯃꯨ ꯅꯠꯇ꯭ꯔꯒ ꯀꯣꯜ ꯇꯧꯗꯕꯥ ꯁꯝꯄꯜ ꯑꯗꯨ ꯁꯤꯖꯤꯟꯅꯥꯏ꯫",
